on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, pack, or generated odds are incomplete.
do $$
declare
  pulsing_aura_cards integer;
  pulsing_aura_packs integer;
  pulsing_aura_odds integer;
begin
  select count(*)
  into pulsing_aura_cards
  from public.cards
  where set_id = 'B3';

  select count(*)
  into pulsing_aura_packs
  from public.packs
  where set_id = 'B3';

  select count(*)
  into pulsing_aura_odds
  from public.card_pack_odds
  where pack_id = 'b3-pulsing-aura';

  if pulsing_aura_cards <> 234 then
    raise exception
      'Expected 234 Pulsing Aura cards, found %',
      pulsing_aura_cards;
  end if;

  if pulsing_aura_packs <> 1 then
    raise exception
      'Expected 1 Pulsing Aura pack, found %',
      pulsing_aura_packs;
  end if;

  if pulsing_aura_odds <> 234 then
    raise exception
      'Expected 234 Pulsing Aura odds rows, found %',
      pulsing_aura_odds;
  end if;
end
$$;

commit;

-- Expected: 234 total records for the Pulsing Aura pack.
select
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id = 'b3-pulsing-aura'
group by cards.rarity
order by min(cards.collector_number);
